<?php namespace App\Http\Requests; use Illuminate\Foundation\Http\FormRequest; class ReminderRequest extends FormRequest { public function authorize(): bool{return $this->user()!==null;} public function rules(): array{return ['pet_id'=>'nullable|exists:pets,id','type'=>'required|in:vaccination,grooming,medication,checkup,custom','title'=>'required|string|max:255','notes'=>'nullable|string','due_at'=>'required|date'];} }